CREATE SCHEMA IF NOT EXISTS engine;
CREATE TABLE engine.run (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, public_id varchar(80) UNIQUE NOT NULL,
 app_code varchar(64) NOT NULL, app_version_id bigint, debug_snapshot jsonb, eval_candidate jsonb,
 trigger_type varchar(16) NOT NULL CHECK(trigger_type IN ('CHAT','TASK','DEBUG','EVALUATION')),
 status varchar(24) NOT NULL CHECK(status IN ('PENDING','RUNNING','WAITING_STEP','WAITING_APPROVAL','WAITING_EXTERNAL','SUCCEEDED','FAILED','CANCELLED')),
 stop_reason varchar(32), principal_id varchar(64) NOT NULL,tenant_id varchar(64) NOT NULL,conversation_id bigint,
 input_ref varchar(256) NOT NULL,output_ref varchar(256),version_refs jsonb NOT NULL,guard_ctx jsonb NOT NULL,budget jsonb NOT NULL,
 started_at timestamptz DEFAULT now(),ended_at timestamptz, snapshot jsonb NOT NULL, inputs jsonb NOT NULL, output jsonb,error jsonb,
 event_seq int NOT NULL DEFAULT 0, mode varchar(24) NOT NULL DEFAULT 'FULL',request_id varchar(128),
 CHECK ((trigger_type IN ('CHAT','TASK') AND app_version_id IS NOT NULL AND debug_snapshot IS NULL AND eval_candidate IS NULL)
 OR(trigger_type='DEBUG' AND app_version_id IS NULL AND debug_snapshot IS NOT NULL AND eval_candidate IS NULL)
 OR(trigger_type='EVALUATION' AND ((app_version_id IS NOT NULL)::int+(eval_candidate IS NOT NULL)::int)=1 AND debug_snapshot IS NULL)),
 UNIQUE(tenant_id,principal_id,request_id)
);
CREATE INDEX idx_run_tenant ON engine.run(tenant_id,started_at DESC);
CREATE TABLE engine.node_instance (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,run_id bigint NOT NULL REFERENCES engine.run(id),node_def_id varchar(64),step_seq int NOT NULL,node_type varchar(16) NOT NULL,join_semantics varchar(8),
 status varchar(24) NOT NULL CHECK(status IN ('READY','RUNNING','WAITING_STEP','WAITING_APPROVAL','WAITING_EXTERNAL','SUCCEEDED','FAILED','SKIPPED','ABANDONED','CANCELLED')),
 lease_owner varchar(64),lease_until timestamptz,committed_attempt_id bigint,committed_output_ref varchar(256),error jsonb,input_digest char(64),output_digest char(64),started_at timestamptz,ended_at timestamptz,
 pause_seq int, released boolean NOT NULL DEFAULT false, output jsonb,definition jsonb NOT NULL, winner_node_id bigint,
 UNIQUE(run_id,step_seq),UNIQUE(run_id,node_def_id)
);
CREATE TABLE engine.attempt (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,node_instance_id bigint NOT NULL REFERENCES engine.node_instance(id),attempt_no int NOT NULL,status varchar(16) NOT NULL,
 idempotency_key char(64) NOT NULL,request_snapshot_ref varchar(256) NOT NULL,routed_model jsonb,response_ref varchar(256),error jsonb,started_at timestamptz DEFAULT now(),ended_at timestamptz,
 request_snapshot jsonb NOT NULL,response jsonb,checkpoint jsonb NOT NULL DEFAULT '{}',UNIQUE(node_instance_id,attempt_no)
);
CREATE TABLE engine.tool_call (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,run_id bigint NOT NULL REFERENCES engine.run(id),node_instance_id bigint NOT NULL REFERENCES engine.node_instance(id),call_seq int NOT NULL,skill_version_id bigint NOT NULL,args_digest char(64) NOT NULL,args_ref varchar(256),idempotency_key char(64) NOT NULL UNIQUE,
 status varchar(16) NOT NULL CHECK(status IN ('REGISTERED','SUBMITTED','EXECUTING','SUCCEEDED','FAILED','UNKNOWN','ABANDONED')),
 claimed_by varchar(64),claimed_at timestamptz,claimed_lease timestamptz,is_mock boolean NOT NULL DEFAULT false,duration_ms int,error_semantic varchar(32),result_ref varchar(256),created_at timestamptz DEFAULT now(),
 skill_code varchar(64) NOT NULL,args jsonb NOT NULL,result jsonb,attempt_id bigint NOT NULL REFERENCES engine.attempt(id), UNIQUE(node_instance_id,call_seq)
);
CREATE TABLE engine.run_event(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,run_id bigint NOT NULL REFERENCES engine.run(id),seq int NOT NULL,type varchar(32) NOT NULL,payload jsonb NOT NULL,created_at timestamptz DEFAULT now(),UNIQUE(run_id,seq));
CREATE UNIQUE INDEX resume_request_once ON engine.run_event(run_id,(payload->>'requestId')) WHERE type='RESUMED';
CREATE TABLE engine.attempt_note(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,node_instance_id bigint NOT NULL,attempt_id bigint,kind varchar(40) NOT NULL,payload jsonb,created_at timestamptz DEFAULT now());

